package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.SubtypeResolver;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class StdSubtypeResolver_collectAndResolveSubtypesByTypeId_TriageGen1Test {

    private StdSubtypeResolver resolver;
    private MapperConfig<?> config;
    private AnnotationIntrospector ai;
    private JavaType baseType;
    private AnnotatedMember property;

    // Dummy classes for testing hierarchy
    public static class Base {}
    public static class Sub extends Base {}
    public static class Unrelated {}

    @Before
    public void setUp() {
        resolver = new StdSubtypeResolver();
        config = mock(MapperConfig.class);
        ai = mock(AnnotationIntrospector.class);
        baseType = mock(JavaType.class);
        property = mock(AnnotatedMember.class);

        when(config.getAnnotationIntrospector()).thenReturn(ai);
        when(baseType.getRawClass()).thenReturn(Base.class);
    }

    @Test
    public void testCollectSubtypes_MinimalCase() {
        // Test case: No property, no registered subtypes, just base type
        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, null, baseType);

        assertNotNull(result);
        // Should at least contain the root type itself (via _combineNamedAndUnnamed logic)
        boolean foundBase = false;
        for (NamedType nt : result) {
            if (nt.getType().equals(Base.class)) {
                foundBase = true;
                break;
            }
        }
        assertTrue("Result should contain the base type", foundBase);
    }

    @Test
    public void testCollectSubtypes_WithPropertySubtypes() {
        // Test case: Subtypes found via AnnotationIntrospector on the property
        NamedType propertySubtype = new NamedType(Sub.class, "sub");
        when(ai.findSubtypes(property)).thenReturn(Collections.singletonList(propertySubtype));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        assertNotNull(result);
        boolean foundSub = false;
        for (NamedType nt : result) {
            if (nt.getType().equals(Sub.class)) {
                foundSub = true;
                break;
            }
        }
        assertTrue("Should have found subtype from property annotations", foundSub);
    }

    @Test
    public void testCollectSubtypes_WithRegisteredSubtypes() {
        // Test case: Subtypes found via explicit registration
        resolver.registerSubtypes(new NamedType(Sub.class, "sub"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, null, baseType);

        assertNotNull(result);
        boolean foundSub = false;
        for (NamedType nt : result) {
            if (nt.getType().equals(Sub.class)) {
                foundSub = true;
                break;
            }
        }
        assertTrue("Should have found registered subtype", foundSub);
    }

    @Test
    public void testCollectSubtypes_WithRegisteredUnrelatedSubtypes() {
        // Test case: Registered subtype is NOT a subclass of baseType (should be ignored)
        resolver.registerSubtypes(new NamedType(Unrelated.class, "unrelated"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, null, baseType);

        assertNotNull(result);
        for (NamedType nt : result) {
            assertNotEquals("Should not include unrelated registered type", Unrelated.class, nt.getType());
        }
    }

    @Test
    public void testCollectSubtypes_PrecedenceAndDuplicates() {
        // Test case: Property provides a subtype, and registration provides the same subtype
        // This tests the 'typesHandled' Set logic to ensure no duplicates/infinite loops
        NamedType subType = new NamedType(Sub.class, "sub");

        when(ai.findSubtypes(property)).thenReturn(Collections.singletonList(subType));
        resolver.registerSubtypes(subType);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        int subCount = 0;
        for (NamedType nt : result) {
            if (nt.getType().equals(Sub.class)) {
                subCount++;
            }
        }
        // Depending on implementation of _combineNamedAndUnnamed, it should handle duplicates via typesHandled
        assertTrue("Should handle subtypes without crashing or duplicate processing", subCount >= 1);
    }

    @Test
    public void testCollectSubtypes_PropertyReturnsNull() {
        // Test case: ai.findSubtypes(property) returns null
        when(ai.findSubtypes(property)).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        assertNotNull(result);
        // Should still return base type
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Base.class)));
    }

    @Test
    public void testCollectSubtypes_AllFeaturesCombined() {
        // Test case: Root + Property + Registration
        NamedType propSub = new NamedType(Sub.class, "propSub");
        NamedType regSub = new NamedType(Sub.class, "regSub");

        when(ai.findSubtypes(property)).thenReturn(Collections.singletonList(propSub));
        resolver.registerSubtypes(regSub);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        assertNotNull(result);
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Base.class)));
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Sub.class)));
    }
}
